    long beforeVerticesCount = getVerticesCount(service.getGraph());
    long beforeEdgesCount = getEdgesCount(service.getGraph());
    WorkflowExecutionContext context = WorkflowExecutionContext.create(getTestMessageArgs(EntityOperations.REPLICATE, REPLICATION_WORKFLOW_NAME, REPLICATED_FEED, "jail://global:00/falcon/raw-click/bcp/20140101", "jail://global:00/falcon/raw-click/primary/20140101", REPLICATED_FEED), WorkflowExecutionContext.Type.POST_PROCESSING);
    service.onSuccess(context);
    debug(service.getGraph());
    GraphUtils.dump(service.getGraph());
    verifyFeedEntityEdges(REPLICATED_FEED, "Secure", "analytics");
    verifyLineageGraphForReplicationOrEviction(REPLICATED_FEED, "jail://global:00/falcon/raw-click/bcp/20140101", context, RelationshipLabel.FEED_CLUSTER_REPLICATED_EDGE);
    // +1 for the new instance vertex added
    Assert.assertEquals(getVerticesCount(service.getGraph()), beforeVerticesCount + 1);
    // +6 = instance-of, stored-in, owned-by, classification, group, replicated-to
    Assert.assertEquals(getEdgesCount(service.getGraph()), beforeEdgesCount + 6);
}

@Test
public void testLineageForRetention() throws Exception {
    setupForLineageEviction();
    WorkflowExecutionContext context = WorkflowExecutionContext.create(getTestMessageArgs(EntityOperations.DELETE, EVICTION_WORKFLOW_NAME, EVICTED_FEED, EVICTED_INSTANCE_PATHS, "IGNORE", EVICTED_FEED), WorkflowExecutionContext.Type.POST_PROCESSING);
    service.onSuccess(context);
    debug(service.getGraph());
    GraphUtils.dump(service.getGraph());
    List<String> expectedFeeds = Arrays.asList("impression-feed/2014-01-01T00:00Z", "clicks-feed/2014-01-01T00:00Z", "imp-click-join1/2014-01-01T00:00Z", "imp-click-join1/2014-01-02T00:00Z");
    List<String> secureFeeds = Arrays.asList("impression-feed/2014-01-01T00:00Z", "clicks-feed/2014-01-01T00:00Z");
    List<String> ownedAndSecureFeeds = Arrays.asList("clicks-feed/2014-01-01T00:00Z", "imp-click-join1/2014-01-01T00:00Z", "imp-click-join1/2014-01-02T00:00Z");
    verifyLineageGraph(RelationshipType.FEED_INSTANCE.getName(), expectedFeeds, secureFeeds, ownedAndSecureFeeds);
    String[] paths = EVICTED_INSTANCE_PATHS.split(EvictedInstanceSerDe.INSTANCEPATH_SEPARATOR);
    for (String feedInstanceDataPath : paths) {
        verifyLineageGraphForReplicationOrEviction(EVICTED_FEED, feedInstanceDataPath, context, RelationshipLabel.FEED_CLUSTER_EVICTED_EDGE);
    }
    // No new vertices added
    Assert.assertEquals(getVerticesCount(service.getGraph()), 23);
    // +1 =  +2 for evicted-from edge from Feed Instance vertex to cluster.
    // -1 imp-click-join1 is added twice instead of imp-click-join2 so there is one less edge as there is no
    // classified-as -> Secure edge.
    Assert.assertEquals(getEdgesCount(service.getGraph()), 72);
}

