/**
 * Filter entities by status (SUBMITTED or RUNNING).
 */
@Test(dataProvider = "getHelpers")
public void listEntitiesWithFilterByStatus(AbstractEntityHelper helper) throws AuthenticationException, IOException, URISyntaxException, InterruptedException {
    String[] statuses = helper.getEntityType().equalsIgnoreCase("cluster") ? new String[] { "SUBMITTED" } : new String[] { "SUBMITTED", "RUNNING" };
    EntityElement[] allEntities = helper.listAllEntities("fields=status", null).getEntityList().getElements();
    int[] counters = new int[statuses.length];
    for (EntityElement entity : allEntities) {
        for (int i = 0; i < statuses.length; i++) {
            if (statuses[i].equals(entity.status)) {
                counters[i]++;
            }
        }
    }
    for (int i = 0; i < statuses.length; i++) {
        EntityElement[] entities = helper.listAllEntities("fields=status&filterBy=STATUS:" + statuses[i], null).getEntityList().getElements();
        Assert.assertEquals(entities.length, counters[i], "Number of entities is not correct with status=" + statuses[i]);
        for (EntityElement entity : entities) {
            Assert.assertEquals(entity.status, statuses[i], "Entity should has status " + statuses[i] + ". Entity: " + entity);
        }
    }
}

/**
 * Testing offset parameter. Checking number of entities and order.
 */
@Test(dataProvider = "getHelpers")
public void listEntitiesWithOffset(AbstractEntityHelper helper) throws AuthenticationException, IOException, URISyntaxException, InterruptedException {
