 */
@Test(dataProvider = "getHelpers")
public void listEntitiesWithCustomFilter(AbstractEntityHelper helper) throws AuthenticationException, IOException, URISyntaxException, InterruptedException {
    EntityElement[] entities = helper.listEntities("numResults=2&fields=status,tags&filterBy=STATUS:SUBMITTED&orderBy=name&tags=" + tags[2], null).getEntityList().getElements();
    if (entities != null) {
