        softAssert.assertTrue(Ordering.from(NAME_COMPARATOR).isOrdered(Arrays.asList(entities)), helper.getEntityType() + " entities are not ordered by name: " + Arrays.toString(entities));
        softAssert.assertAll();
    }
}

