/**
 * Test navigation from the process instance vertex to its input and output feed instances.
 * @throws Exception
 */
@Test
public void processInstanceToFeedInstanceNodes() throws Exception {
    final VerticesResult processResult = lineageHelper.getVerticesByName(processName);
    GraphAssert.assertVertexSanity(processResult);
    Vertex processVertex = processResult.getResults().get(0);
    final VerticesResult processIncoming = lineageHelper.getVerticesByDirection(processVertex.getId(), Direction.inComingVertices);
    GraphAssert.assertVertexSanity(processIncoming);
    // fetching process instance vertex
    final List<Vertex> piVertices = processIncoming.filterByType(Vertex.VERTEX_TYPE.PROCESS_INSTANCE);
    LOGGER.info("process instance vertex = " + piVertices);
    // fetching process instances info
    InstancesResult piResult = prism.getProcessHelper().getProcessInstanceStatus(processName, "?start=" + processStartDate + "&end=" + endDate);
    Assert.assertEquals(piVertices.size(), piResult.getInstances().length, "Number of process instances should be same weather it is retrieved from lineage api " + "or falcon rest api");
    final List<String> allowedPITimes = new ArrayList<String>();
    for (InstancesResult.Instance processInstance : piResult.getInstances()) {
        allowedPITimes.add(processInstance.getInstance());
    }
    for (Vertex piVertex : piVertices) {
        Assert.assertTrue(piVertex.getName().startsWith(processName), "Process instance names should start with process name: " + piVertex.getName());
        String processInstanceTime = piVertex.getName().substring(processName.length() + 1);
        LOGGER.info("processInstanceTime = " + processInstanceTime);
        Assert.assertTrue(allowedPITimes.remove(processInstanceTime), "Unexpected processInstanceTime: " + processInstanceTime + "it should have been be in the list " + allowedPITimes);
        VerticesResult piIncoming = lineageHelper.getVerticesByDirection(piVertex.getId(), Direction.inComingVertices);
        GraphAssert.assertVertexSanity(piIncoming);
        //process input start="now(0,-20) and end is "now(0,0)"
        //frequency of the feed is 5 min so there are 5 instances
        Assert.assertEquals(piIncoming.getTotalSize(), 5);
        final List<String> allowedInpFeedInstDates = TimeUtil.getMinuteDatesOnEitherSide(TimeUtil.oozieDateToDate(processInstanceTime).plusMinutes(-20), TimeUtil.oozieDateToDate(processInstanceTime), 5, OozieUtil.getOozieDateTimeFormatter());
        // checking input feed instances
        for (Vertex inFeedInst : piIncoming.filterByType(Vertex.VERTEX_TYPE.FEED_INSTANCE)) {
            final String inFeedInstName = inFeedInst.getName();
            Assert.assertTrue(inFeedInstName.startsWith(inputFeedName), "input feed instances should start with input feed name: " + inFeedInstName);
            final String inFeedInstanceTime = inFeedInstName.substring(inputFeedName.length() + 1);
            LOGGER.info("inFeedInstanceTime = " + inFeedInstanceTime);
            Assert.assertTrue(allowedInpFeedInstDates.remove(inFeedInstanceTime), "Unexpected inFeedInstanceTime: " + inFeedInstanceTime + " it should have " + "been present in: " + allowedInpFeedInstDates);
        }
        VerticesResult piOutgoing = lineageHelper.getVerticesByDirection(piVertex.getId(), Direction.outgoingVertices);
        GraphAssert.assertVertexSanity(piOutgoing);
        Assert.assertEquals(piOutgoing.filterByType(Vertex.VERTEX_TYPE.FEED_INSTANCE).size(), 1, "Expected only one output feed instance.");
        // checking output feed instances
        final Vertex outFeedInst = piOutgoing.filterByType(Vertex.VERTEX_TYPE.FEED_INSTANCE).get(0);
        final String outFeedInstName = outFeedInst.getName();
        Assert.assertTrue(outFeedInstName.startsWith(outputFeedName), "Expecting outFeedInstName: " + outFeedInstName + " to start with outputFeedName: " + outputFeedName);
        final String outFeedInstanceTime = outFeedInstName.substring(outputFeedName.length() + 1);
        Assert.assertEquals(outFeedInstanceTime, processInstanceTime, "Expecting output feed instance time and process instance time to be same");
    }
}

