    Assert.assertEquals(bothVerticesIds.getTotalSize(), inputFeeds.length + outputFeeds.length + 2, "There should be edge from the cluster to inputFeeds & outputFeeds," + " one between cluster and colo, one between cluster and classification");
    final VertexIdsResult incomingVerticesIds = lineageHelper.getVertexIdsByDirection(clusterVertexId, Direction.incomingVerticesIds);
    for (Integer vertexId : incomingVerticesIds.getResults()) {
        Assert.assertTrue(vertexId > 0, "Vertex id should be valid.");
    }
    Assert.assertEquals(incomingVerticesIds.getTotalSize(), inputFeeds.length + outputFeeds.length, "There should be edge from the cluster to inputFeeds & outputFeeds and one " + "between cluster and colo");
    final VertexIdsResult outgoingVerticesIds = lineageHelper.getVertexIdsByDirection(clusterVertexId, Direction.outgoingVerticesIds);
    for (Integer vertexId : outgoingVerticesIds.getResults()) {
        Assert.assertTrue(vertexId > 0, "Vertex id should be valid.");
    }
    Assert.assertEquals(outgoingVerticesIds.getTotalSize(), 2, "There should be an edge from the cluster to colo and one from cluster to " + "classification");
}

