/**
 * List process instances using orderBy - status, -startTime, -endTime params, expecting list of
 * process instances in the right order.
 */
@Test
public void testProcessOrderBy() throws Exception {
    SoftAssert softAssert = new SoftAssert();
    //orderBy startTime descending order
    InstancesResult r = prism.getProcessHelper().listInstances(processName, "orderBy=startTime&sortOrder=desc", null);
    InstancesResult.Instance[] instances = r.getInstances();
    Date previousDate = new Date();
    for (InstancesResult.Instance instance : instances) {
        Date current = instance.getStartTime();
        if (current != null) {
            //e.g if instance is WAITING it doesn't have start time
            softAssert.assertTrue(current.before(previousDate) || current.equals(previousDate), "Wrong order. Current startTime :" + current + " Previous: " + previousDate);
            previousDate = (Date) current.clone();
        }
    }
    //suspend one instance and kill another one to create variety of statuses
    r = prism.getProcessHelper().getProcessInstanceSuspend(processName, "?start=" + TimeUtil.addMinsToTime(startTime, 4) + "&end=" + TimeUtil.addMinsToTime(startTime, 8));
    InstanceUtil.validateResponse(r, 1, 0, 1, 0, 0);
    r = prism.getProcessHelper().getProcessInstanceKill(processName, "?start=" + startTime + "&end=" + TimeUtil.addMinsToTime(startTime, 3));
    InstanceUtil.validateResponse(r, 1, 0, 0, 0, 1);
    //wait till instances status be stable
    InstanceUtil.waitTillInstanceReachState(clusterOC, processName, 3, CoordinatorAction.Status.RUNNING, EntityType.PROCESS, 3);
    //orderBy status ascending order
    r = prism.getProcessHelper().listInstances(processName, "start=" + startTime + "&numResults=12&orderBy=status&sortOrder=desc", null);
    InstanceUtil.validateResponse(r, 12, 3, 1, 7, 1);
    instances = r.getInstances();
    InstancesResult.WorkflowStatus previousStatus = InstancesResult.WorkflowStatus.WAITING;
    for (InstancesResult.Instance instance : instances) {
        InstancesResult.WorkflowStatus current = instance.getStatus();
        softAssert.assertTrue(current.toString().compareTo(previousStatus.toString()) <= 0, "Wrong order. Compared " + current + " and " + previousStatus + " statuses.");
        previousStatus = current;
    }
    //only instances which already have finished have endTime
    InstanceUtil.waitTillInstanceReachState(clusterOC, processName, 2, CoordinatorAction.Status.SUCCEEDED, EntityType.PROCESS, 10);
    //sort by end time, descending order
    r = prism.getProcessHelper().listInstances(processName, "start=" + startTime + "&numResults=12&orderBy=endTime&sortOrder=desc", null);
    instances = r.getInstances();
    previousDate = new Date();
    for (InstancesResult.Instance instance : instances) {
        Date current = instance.getEndTime();
        if (current != null) {
            //e.g if instance is WAITING it doesn't have end time
            softAssert.assertTrue(current.before(previousDate) || current.equals(previousDate), "Wrong order. Current startTime :" + current + " Previous: " + previousDate);
            previousDate = (Date) current.clone();
        }
    }
    softAssert.assertAll();
}

