/**
 * Test cases:
 * -list processes with pipeline name having special or UTF-8 chars expecting request to fail.
 * -list processes with invalid or long pipeline name expecting request to pass.
 * -submit a process with pipeline name with special or UTF-8 chars expecting submission to fail.
 * -submit a process with a long pipeline name or many comma separated names process submission
 * to go through.
 *
 * @param pipeline pipeline name
 * @param action list or submit entities
 * @param shouldSucceed should action succeed or not
 */
@Test(dataProvider = "data")
public void testPipelines(String pipeline, String action, boolean shouldSucceed) throws URISyntaxException, IOException, AuthenticationException, JAXBException, InterruptedException {
    bundles[0].setProcessPipeline(pipeline);
    if (action.equals("list")) {
        if (shouldSucceed) {
            AssertUtil.assertSucceeded(cluster.getProcessHelper().getListByPipeline(pipeline));
        } else {
            AssertUtil.assertFailed(cluster.getProcessHelper().getListByPipeline(pipeline));
        }
    } else {
        bundles[0].submitProcess(shouldSucceed);
    }
}

@Test(dataProvider = "DP", groups = { "0.2.2", "retry" }, enabled = true)
public void testRetryInProcessZeroAttemptUpdate(Retry retry) throws Exception {
    for (String data : bundles[0].getDataSets()) {
        AssertUtil.assertSucceeded(prism.getFeedHelper().submitEntity(data));
    }
    bundles[0].setRetry(retry);
    //submit and schedule process
    ServiceResponse response = prism.getProcessHelper().submitEntity(bundles[0].getProcessData());
    if (retry.getAttempts() <= 0 || retry.getDelay().getFrequencyAsInt() <= 0) {
        AssertUtil.assertFailed(response);
    } else {
        AssertUtil.assertSucceeded(response);
        // lets create data now:
        HadoopUtil.deleteDirIfExists(lateDir, clusterFS);
        HadoopUtil.lateDataReplenish(clusterFS, 20, 0, lateDir);
        //schedule process
        AssertUtil.assertSucceeded(prism.getProcessHelper().schedule(bundles[0].getProcessData()));
        //now wait till the process is over
        String bundleId = OozieUtil.getBundles(clusterOC, Util.readEntityName(bundles[0].getProcessData()), EntityType.PROCESS).get(0);
        waitTillCertainPercentageOfProcessHasStarted(clusterOC, bundleId, 25);
        int defaultRetries = bundles[0].getProcessObject().getRetry().getAttempts();
        retry.setAttempts((0));
        bundles[0].setRetry(retry);
        LOGGER.info("going to update process at:" + DateTime.now(DateTimeZone.UTC));
        prism.getProcessHelper().update((bundles[0].getProcessData()), bundles[0].getProcessData());
        String newBundleId = InstanceUtil.getLatestBundleID(cluster, Util.readEntityName(bundles[0].getProcessData()), EntityType.PROCESS);
        Assert.assertEquals(bundleId, newBundleId, "its creating a new bundle!!!");
        //now to validate all failed instances to check if they were retried or not.
        validateRetry(clusterOC, bundleId, defaultRetries);
        checkIfRetriesWereTriggeredCorrectly(cluster, retry, bundleId);
    }
}

