    feed = FeedMerlin.fromString(feed).clearFeedClusters().toString();
    feed = FeedMerlin.fromString(feed).addFeedCluster(new FeedMerlin.FeedClusterBuilder(Util.readEntityName(bundles[0].getClusters().get(0))).withRetention("days(1000000)", ActionType.DELETE).withValidity(startTimeUA1, "2012-10-01T12:10Z").withClusterType(ClusterType.SOURCE).withDataLocation(testBaseDir1 + MINUTE_DATE_PATTERN).build()).toString();
    feed = FeedMerlin.fromString(feed).addFeedCluster(new FeedMerlin.FeedClusterBuilder(Util.readEntityName(bundles[1].getClusters().get(0))).withRetention("days(1000000)", ActionType.DELETE).withValidity(startTimeUA2, "2012-10-01T12:25Z").withClusterType(ClusterType.TARGET).withPartition("${cluster.colo}").withDataLocation(testBaseDir2 + MINUTE_DATE_PATTERN).build()).toString();
    feed = FeedMerlin.fromString(feed).addFeedCluster(new FeedMerlin.FeedClusterBuilder(Util.readEntityName(bundles[2].getClusters().get(0))).withRetention("days(1000000)", ActionType.DELETE).withValidity("2012-10-01T12:00Z", "2099-01-01T00:00Z").withClusterType(ClusterType.SOURCE).build()).toString();
