        compareDataStoreStates(systemPostUp.get("ua1Archive"), finalUA1ArchiveStore, clusterName);
    } catch (Exception e) {
        LOGGER.info(e.getMessage());
        throw new TestNGException(e.getMessage());
    } finally {
        Util.restartService(cluster2.getClusterHelper());
    }
}

