@Test(groups = { "MultiCluster", "0.3.1", "distributed" }, timeOut = 1200000, enabled = true)
public void inNextFewMinutesUpdateRollForwardProcess() throws JAXBException, IOException, URISyntaxException, JSchException, OozieClientException, SAXException, AuthenticationException, InterruptedException {
    /*
        submit process on 3 clusters. Schedule on 2 clusters. Bring down one of
        the scheduled cluster. Update with time 5 minutes from now. On running
        cluster new coord should be created with start time +5 and no instance
        should be missing. On 3rd cluster where process was only submit,
        definition should be updated. Bring the down cluster up. Update with same
        definition again, now the recently up cluster should also have new
        coords.
        */
    try {
        Util.startService(cluster2.getProcessHelper());
        String startTime = TimeUtil.getTimeWrtSystemTime(-15);
        processBundle.setProcessValidity(startTime, TimeUtil.getTimeWrtSystemTime(60));
        processBundle.addClusterToBundle(bundles[1].getClusters().get(0), ClusterType.SOURCE, null, null);
        processBundle.addClusterToBundle(bundles[2].getClusters().get(0), ClusterType.SOURCE, null, null);
        processBundle.submitBundle(prism);
        //schedule of 2 cluster
        cluster1.getProcessHelper().schedule(processBundle.getProcessData());
        cluster2.getProcessHelper().schedule(processBundle.getProcessData());
        InstanceUtil.waitTillInstancesAreCreated(cluster2, processBundle.getProcessData(), 0);
        //shut down cluster2
        Util.shutDownService(cluster2.getProcessHelper());
        // save old data before update
        String oldProcess = processBundle.getProcessData();
        String oldBundleIDCluster1 = InstanceUtil.getLatestBundleID(cluster1, Util.readEntityName(oldProcess), EntityType.PROCESS);
        String oldBundleIDCluster2 = InstanceUtil.getLatestBundleID(cluster2, Util.readEntityName(oldProcess), EntityType.PROCESS);
        List<String> oldNominalTimesCluster1 = OozieUtil.getActionsNominalTime(cluster1, oldBundleIDCluster1, EntityType.PROCESS);
        List<String> oldNominalTimesCluster2 = OozieUtil.getActionsNominalTime(cluster2, oldBundleIDCluster2, EntityType.PROCESS);
        //update process validity
        processBundle.setProcessProperty("someProp", "someValue");
        //send update request
        String updateTime = TimeUtil.getTimeWrtSystemTime(5);
        ServiceResponse r = prism.getProcessHelper().update(oldProcess, processBundle.getProcessData(), updateTime);
        AssertUtil.assertPartial(r);
        InstanceUtil.waitTillInstancesAreCreated(cluster1, processBundle.getProcessData(), 1);
        //verify new bundle on cluster1 and definition on cluster3
        OozieUtil.verifyNewBundleCreation(cluster1, oldBundleIDCluster1, oldNominalTimesCluster1, oldProcess, true, false);
        OozieUtil.verifyNewBundleCreation(cluster2, oldBundleIDCluster2, oldNominalTimesCluster2, oldProcess, false, false);
        String definitionCluster3 = Util.getEntityDefinition(cluster3, processBundle.getProcessData(), true);
        Assert.assertTrue(XmlUtil.isIdentical(definitionCluster3, processBundle.getProcessData()), "Process definitions should be equal");
        //start the stopped cluster2
        Util.startService(cluster2.getProcessHelper());
        TimeUtil.sleepSeconds(40);
        String newBundleIdCluster1 = InstanceUtil.getLatestBundleID(cluster1, Util.readEntityName(oldProcess), EntityType.PROCESS);
        //send second update request
        r = prism.getProcessHelper().update(oldProcess, processBundle.getProcessData(), updateTime, null);
        AssertUtil.assertSucceeded(r);
        String defCluster2 = Util.getEntityDefinition(cluster2, processBundle.getProcessData(), true);
        LOGGER.info("defCluster2 : " + Util.prettyPrintXml(defCluster2));
        // verify new bundle in cluster2 and no new bundle in cluster1  and
        OozieUtil.verifyNewBundleCreation(cluster1, newBundleIdCluster1, oldNominalTimesCluster1, oldProcess, false, false);
        OozieUtil.verifyNewBundleCreation(cluster2, oldBundleIDCluster2, oldNominalTimesCluster2, oldProcess, true, false);
        //wait till update time is reached
        TimeUtil.sleepTill(updateTime);
        OozieUtil.verifyNewBundleCreation(cluster2, oldBundleIDCluster2, oldNominalTimesCluster2, oldProcess, true, true);
        OozieUtil.verifyNewBundleCreation(cluster1, oldBundleIDCluster1, oldNominalTimesCluster1, oldProcess, true, true);
    } finally {
        Util.restartService(cluster2.getProcessHelper());
    }
}

@Test(groups = { "MultiCluster", "0.3.1", "distributed" }, timeOut = 1200000, enabled = true)
public void inNextFewMinutesUpdateRollForwardFeed() throws JAXBException, IOException, URISyntaxException, JSchException, OozieClientException, SAXException, AuthenticationException, InterruptedException {
    try {
        String startTimeClusterSource = TimeUtil.getTimeWrtSystemTime(-18);
        String feed = getMultiClusterFeed(startTimeClusterSource, startTimeClusterSource);
        LOGGER.info("feed: " + Util.prettyPrintXml(feed));
