        Assert.assertEquals(InstanceUtil.checkIfFeedCoordExist(cluster2.getFeedHelper(), Util.readEntityName(feed), "RETENTION"), 2);
        OozieUtil.verifyNewBundleCreation(cluster1, newBundleCluster1, oldNominalTimesCluster1, feed, false, false);
        //wait till update time is reached
        TimeUtil.sleepTill(TimeUtil.getTimeWrtSystemTime(5));
        //verify new bundle creation with instance matching
        OozieUtil.verifyNewBundleCreation(cluster1, oldBundleCluster1, oldNominalTimesCluster1, feed, true, true);
    } finally {
        Util.restartService(cluster2.getProcessHelper());
    }
}

