    processBundle.submitFeedsScheduleProcess(prism);
    //wait for coord to be in running state
    InstanceUtil.waitTillInstancesAreCreated(cluster1, processBundle.getProcessData(), 0);
    InstanceUtil.waitTillInstancesAreCreated(cluster3, processBundle.getProcessData(), 0);
    //save old info
    String oldBundleIdCluster1 = InstanceUtil.getLatestBundleID(cluster1, Util.readEntityName(processBundle.getProcessData()), EntityType.PROCESS);
    List<String> nominalTimesCluster1 = OozieUtil.getActionsNominalTime(cluster1, oldBundleIdCluster1, EntityType.PROCESS);
    String oldBundleIdCluster2 = InstanceUtil.getLatestBundleID(cluster2, Util.readEntityName(processBundle.getProcessData()), EntityType.PROCESS);
    String oldBundleIdCluster3 = InstanceUtil.getLatestBundleID(cluster3, Util.readEntityName(processBundle.getProcessData()), EntityType.PROCESS);
    List<String> nominalTimesCluster3 = OozieUtil.getActionsNominalTime(cluster3, oldBundleIdCluster3, EntityType.PROCESS);
    //update process
    String updateTime = TimeUtil.addMinsToTime(endTimeCluster1, 3);
    processBundle.setProcessProperty("someProp", "someVal");
    ServiceResponse r = prism.getProcessHelper().update(processBundle.getProcessData(), processBundle.getProcessData(), updateTime, null);
    AssertUtil.assertSucceeded(r);
    //check for new bundle to be created
    OozieUtil.verifyNewBundleCreation(cluster1, oldBundleIdCluster1, nominalTimesCluster1, processBundle.getProcessData(), true, false);
    OozieUtil.verifyNewBundleCreation(cluster3, oldBundleIdCluster3, nominalTimesCluster3, processBundle.getProcessData(), true, false);
    OozieUtil.verifyNewBundleCreation(cluster2, oldBundleIdCluster2, nominalTimesCluster3, processBundle.getProcessData(), true, false);
    //wait till new coord are running on cluster1
    InstanceUtil.waitTillInstancesAreCreated(cluster1, processBundle.getProcessData(), 1);
    OozieUtil.verifyNewBundleCreation(cluster1, oldBundleIdCluster1, nominalTimesCluster1, processBundle.getProcessData(), true, true);
    //verify
    String coordStartTimeCluster3 = OozieUtil.getCoordStartTime(cluster3, processBundle.getProcessData(), 1);
    String coordStartTimeCluster2 = OozieUtil.getCoordStartTime(cluster2, processBundle.getProcessData(), 1);
    DateTime updateTimeOozie = TimeUtil.oozieDateToDate(updateTime);
    Assert.assertTrue(TimeUtil.oozieDateToDate(coordStartTimeCluster3).isAfter(updateTimeOozie) || TimeUtil.oozieDateToDate(coordStartTimeCluster3).isEqual(updateTimeOozie), "new coord start time is not correct");
    Assert.assertFalse(TimeUtil.oozieDateToDate(coordStartTimeCluster2).isEqual(updateTimeOozie), "new coord start time is not correct");
    TimeUtil.sleepTill(updateTime);
    InstanceUtil.waitTillInstancesAreCreated(cluster3, processBundle.getProcessData(), 1);
    //verify that no instance are missing
    OozieUtil.verifyNewBundleCreation(cluster3, oldBundleIdCluster3, nominalTimesCluster3, processBundle.getProcessData(), true, true);
}

