        JMSMessageConsumer subscriber = new JMSMessageConsumer(BROKER_IMPL_CLASS, "", "", BROKER_URL, TOPIC_NAME + "," + SECONDARY_TOPIC_NAME, new WorkflowJobEndNotificationService());
