@Test
public void testProcessMessageCreator() throws Exception {
    Thread t = new Thread() {

        @Override
        public void run() {
            try {
                consumer();
            } catch (AssertionError e) {
                error = e;
            } catch (JMSException ignore) {
                error = null;
            }
        }
    };
    t.start();
    latch.await();
    WorkflowExecutionContext context = WorkflowExecutionContext.create(args, WorkflowExecutionContext.Type.POST_PROCESSING);
    JMSMessageProducer jmsMessageProducer = JMSMessageProducer.builder(context).type(JMSMessageProducer.MessageType.USER).build();
    jmsMessageProducer.sendMessage();
    t.join();
    if (error != null) {
        throw error;
    }
}

