@Test
public void testGetEntityListPagination() throws Exception {
    String user = System.getProperty("user.name");
    Entity process1 = buildProcess("process1", user, "consumer=consumer@xyz.com, owner=producer@xyz.com", "testPipeline,dataReplicationPipeline");
    configStore.publish(EntityType.PROCESS, process1);
    Entity process2 = buildProcess("process2", user, "consumer=consumer@xyz.com, owner=producer@xyz.com", "testPipeline,dataReplicationPipeline");
    configStore.publish(EntityType.PROCESS, process2);
    Entity process3 = buildProcess("process3", user, "", "testPipeline");
    configStore.publish(EntityType.PROCESS, process3);
    Entity process4 = buildProcess("process4", user, "owner=producer@xyz.com", "");
    configStore.publish(EntityType.PROCESS, process4);
    EntityList entityList = this.getEntityList("process", "tags", "PIPELINES:dataReplicationPipeline", "", "name", "desc", 1, 1, "");
    Assert.assertNotNull(entityList.getElements());
    Assert.assertEquals(entityList.getElements().length, 1);
    Assert.assertEquals(entityList.getElements()[0].name, "process1");
    Assert.assertEquals(entityList.getElements()[0].tag.size(), 2);
    Assert.assertEquals(entityList.getElements()[0].tag.get(0), "consumer=consumer@xyz.com");
    Assert.assertEquals(entityList.getElements()[0].status, null);
    entityList = this.getEntityList("process", "pipelines", "", "consumer=consumer@xyz.com, owner=producer@xyz.com", "name", "", 0, 2, "");
    Assert.assertNotNull(entityList.getElements());
    Assert.assertEquals(entityList.getElements().length, 2);
    Assert.assertEquals(entityList.getElements()[1].name, "process2");
    Assert.assertEquals(entityList.getElements()[1].pipelines.size(), 2);
    Assert.assertEquals(entityList.getElements()[1].pipelines.get(0), "testPipeline");
    Assert.assertEquals(entityList.getElements()[0].tag, null);
    entityList = this.getEntityList("process", "pipelines", "", "consumer=consumer@xyz.com, owner=producer@xyz.com", "name", "", 10, 2, "");
    Assert.assertEquals(entityList.getElements().length, 0);
    entityList = this.getEntityList("process", "pipelines", "", "owner=producer@xyz.com", "name", "", 1, 2, "");
    Assert.assertEquals(entityList.getElements().length, 2);
    // Test negative value for numResults, should throw an exception.
    try {
        this.getEntityList("process", "pipelines", "", "consumer=consumer@xyz.com, owner=producer@xyz.com", "name", "", 10, -1, "");
        Assert.assertTrue(false);
    } catch (Throwable e) {
        Assert.assertTrue(true);
    }
    // Test invalid entry for sortOrder
    try {
        this.getEntityList("process", "pipelines", "", "consumer=consumer@xyz.com, owner=producer@xyz.com", "name", "invalid", 10, 2, "");
        Assert.assertTrue(false);
    } catch (Throwable e) {
        Assert.assertTrue(true);
    }
}

